}\n                  })\n                ],\n                1\n              ),\n              _vm._v(\" \"),\n              _c(\n                \"div\",\n                {\n                  class: { btn: _vm.modalElement, \"d-none\": !_vm.modalElement },\n                  staticStyle: { width: \"140px\" }\n                },\n                [\n                  _c(\n                    \"div\",\n                    {\n                      attrs: {\n                        onclick:\n                          \"$('.close').click(); $('.basket-preview-wrapper').hide(); event.preventDefault()\"\n                      }\n                    },\n                    [\n                      _c(\"user-login-handler\", {\n                        staticClass: \"register-btn-none\",\n                        attrs: {\n                          \"show-login\": false,\n                          \"show-registration\": true\n                        }\n                      }),\n                      _vm._v(\" \"),\n                      _c(\n                        \"a\",\n                        {\n                          staticClass:\n                            \"btn btn-primary btn-appearance btn-medium register-btn\",\n                          staticStyle: { color: \"#FFFFFF\" },\n                          attrs: {\n                            \"data-testing\": \"register-select\",\n                            \"data-toggle\": \"modal\",\n                            href: \"#registration\"\n                          }\n                        },\n                        [\n                          _c(\"i\", {\n                            staticClass: \"fa fa-user-plus\",\n                            attrs: { \"aria-hidden\": \"true\" }\n                          }),\n                          _vm._v(\n                            \"\\n\\t\\t\\t\\t\\t\\t\\t\\t\" +\n                              _vm._s(\n                                _vm.$translate(\"Ceres::Template.